
begin;
update cda_orc_categorias c set descritivo_calculo='Descriminação da subcategoria de despesas diversas da mao de obra gerencial especifica. Está prevista hospedagem em uma unidade do Booking ou similar, apartamento/casa de 03 quartos para acomodação de até 06 profissionais em São Paulo, por até 05 dias, com diária prevista de R$ 500,00.'
from cda_orc_tipos_projeto t where t.id=c.tipo_id and t.codigo=1 and c.codigo='9.2.2' and (c.descritivo_calculo is null or trim(c.descritivo_calculo)='Descriminação da subcategoria de despesas diversas da mao de obra gerencial especifica');
update cda_orc_formulas_categoria f set definicao=f.definicao||jsonb_build_object('tipo_despesa','hospedagem','quantidade',5,'valor',500,'unidade','diária do imóvel','aplicacao','evento'),atualizado_em=now()
from cda_orc_categorias c join cda_orc_tipos_projeto t on t.id=c.tipo_id where f.categoria_id=c.id and t.codigo=1 and c.codigo='9.2.2';
update cda_orc_cadastros_projeto p set conteudo=(select jsonb_agg(case when c.id is not null then x||jsonb_build_object('formula',coalesce(x->'formula',f.definicao)||jsonb_build_object('tipo_despesa','hospedagem','quantidade',5,'valor',500,'unidade','diária do imóvel','aplicacao','evento'))||case when not(x ? 'descritivo_calculo') or x->>'descritivo_calculo' is null or trim(x->>'descritivo_calculo')='Descriminação da subcategoria de despesas diversas da mao de obra gerencial especifica' then jsonb_build_object('descritivo_calculo',c.descritivo_calculo) else '{}'::jsonb end else x end order by ord) from jsonb_array_elements(p.conteudo) with ordinality z(x,ord) left join cda_orc_categorias c on c.id::text=x->>'id' and c.codigo='9.2.2' left join cda_orc_formulas_categoria f on f.categoria_id=c.id) where p.chave='categorias';
commit;
